"""Suggested rewrites of existing tests: written next to the report, applied only on request."""

from __future__ import annotations

from pathlib import Path

from .config import AppConfig
from .llm_client import LlmClient
from .llm_test_code import ask_for_test_code, write_test_code
from .models import SourceAnalysis, TestTarget
from .prompts import build_update_tests_prompt
from .repo_paths import is_test_file_name, relative_to_repo


SUGGESTED_HEADER = (
    "# This is a suggested update generated by AI Unit Test Assistant.\n"
    "# Review before replacing the original test file.\n"
)


def _suggested_path_for(
    test_file: Path, suggestions_dir: Path, repo_root: Path
) -> Path:
    return suggestions_dir / (relative_to_repo(test_file, repo_root) or Path(test_file.name))


def suggest_test_updates(
    llm: LlmClient,
    config: AppConfig,
    analysis: SourceAnalysis,
    targets: list[TestTarget],
    related_tests: dict[Path, str],
    latest_suggestions: dict[Path, str],
) -> list[Path]:
    """Write an updated version of every related test file; return the written paths.

    ``latest_suggestions`` holds the versions suggested earlier in this run, by
    test file, and is updated in place. A test file related to several changed
    files is updated from its latest suggestion, so it keeps every file's updates.
    """
    suggested_files: list[Path] = []
    for test_path, original_code in related_tests.items():
        current_code = latest_suggestions.get(test_path, original_code)
        try:
            updated = ask_for_test_code(
                llm, *build_update_tests_prompt(analysis, targets, test_path, current_code)
            )
        except Exception:  # noqa: BLE001 - a failed suggestion must not fail the file: its tests are already written
            continue
        latest_suggestions[test_path] = updated
        suggested = _suggested_path_for(test_path, config.suggestions_dir, config.repo_root)
        write_test_code(suggested, SUGGESTED_HEADER, updated)
        suggested_files.append(suggested)
    return suggested_files


def apply_suggested_updates(
    suggestions_dir: Path,
    repo_root: Path,
    strip_header: bool = True,
) -> tuple[list[Path], list[Path]]:
    """Copy each suggested test file under ``suggestions_dir`` to the same
    relative path under ``repo_root``, overwriting the original test file.

    Only files that look like test files (``test_*.py`` / ``*_test.py`` —
    the same rule test_finder selects them by) and resolve inside
    ``repo_root`` are applied. Anything else is refused: suggestions must
    never be able to overwrite production code, even from a corrupted
    artifact.

    If ``strip_header`` is True, the AI-generated suggestion header is removed
    from the top of each file before it is written.

    Returns ``(applied, skipped)`` paths.
    """
    applied: list[Path] = []
    skipped: list[Path] = []
    if not suggestions_dir.exists():
        return applied, skipped

    resolved_root = repo_root.resolve()
    for src in sorted(suggestions_dir.rglob("*.py")):
        rel = src.relative_to(suggestions_dir)
        dest = (repo_root / rel).resolve()
        if not is_test_file_name(rel.name) or not dest.is_relative_to(resolved_root):
            skipped.append(src)
            continue
        text = src.read_text(encoding="utf-8")
        if strip_header and text.startswith(SUGGESTED_HEADER):
            text = text[len(SUGGESTED_HEADER):].lstrip("\n")
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(text, encoding="utf-8")
        applied.append(dest)
    return applied, skipped
